use std::{error::Error, path::Path, time::Instant};

fn usage() -> libc::rusage {
    let mut usage = std::mem::MaybeUninit::uninit();
    assert_eq!(unsafe { libc::getrusage(libc::RUSAGE_SELF, usage.as_mut_ptr()) }, 0);
    unsafe { usage.assume_init() }
}

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    assert_eq!(args.len(), 4, "DATA CONFIG METRICS ORACLE");
    assert!(!cfg!(debug_assertions));
    assert!(query::CONFIGS.contains(&args[1].as_str()));
    let witness: serde_json::Value = serde_json::from_slice(&std::fs::read(&args[3])?)?;
    let expected: std::collections::BTreeSet<Vec<String>> = serde_json::from_value(witness["rows"].clone())?;
    let decimals = serde_json::from_value(witness["decimal_columns"].clone())?;
    let load_start = Instant::now();
    let data = query::load(Path::new(&args[0]), &args[1])?;
    let load_ms = load_start.elapsed().as_secs_f64() * 1000.;
    for _ in 0..5 {
        let answers = query::run(std::hint::black_box(&data), &args[1]);
        assert_eq!(comparison::normalize_set(query::canonical(&answers), &decimals), expected);
    }
    let mut samples = Vec::new();
    for sample in 0..21 {
        let before = usage();
        let start = Instant::now();
        let answer = query::run(std::hint::black_box(&data), &args[1]);
        let elapsed_ms = start.elapsed().as_secs_f64() * 1000.;
        let after = usage();
        std::hint::black_box(&answer);
        assert_eq!(comparison::normalize_set(query::canonical(&answer), &decimals), expected);
        samples.push(serde_json::json!({"sample":sample,"elapsed_ms":elapsed_ms,
            "minor_faults":after.ru_minflt-before.ru_minflt,"major_faults":after.ru_majflt-before.ru_majflt,
            "peak_rss_kib":after.ru_maxrss,"exact":true}));
    }
    let mut times: Vec<_> = samples.iter().map(|v| v["elapsed_ms"].as_f64().unwrap()).collect();
    times.sort_by(f64::total_cmp);
    let process = usage();
    std::fs::write(&args[2], serde_json::to_vec_pretty(&serde_json::json!({
        "query":query::NAME,"config":args[1],"load_ms":load_ms,"warmups":5,"samples":samples,
        "median_ms":times[times.len()/2],"answer":expected,"all_exact":true,
        "process_minor_faults":process.ru_minflt,"process_major_faults":process.ru_majflt,
        "process_peak_rss_kib":process.ru_maxrss
    }))?)?;
    Ok(())
}

